JAMES_HANE_OLD = '    if rhs < -1e-12 or rhs > 1+1e-12:\n        raise ValueError(f"No real exact-compatibility beta for rhs={rhs}")\n    rhs = min(1.0,max(0.0,rhs))\n'
JAMES_HANE_NEW = '    # Only a machine-roundoff guard is allowed at the acos domain edge.\n    # A genuinely out-of-domain rhs is not silently projected into [0,1].\n    edge_tol = 64.0 * np.finfo(float).eps\n    if rhs < -edge_tol or rhs > 1.0 + edge_tol:\n        raise ValueError(f"No real exact-compatibility beta for rhs={rhs}")\n    if rhs < 0.0:\n        rhs = 0.0\n    elif rhs > 1.0:\n        rhs = 1.0\n'


def run(repo: Path, *args: str, check: bool = True) -> subprocess.CompletedProcess[str]:
    p = subprocess.run(
        list(args), cwd=repo, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE
    )
    if check and p.returncode != 0:
        raise RuntimeError("command failed: " + " ".join(args) + "\n" + p.stdout + p.stderr)
    return p


def git_blob_sha(repo: Path, rel: str) -> str:
    return run(repo, "git", "hash-object", rel).stdout.strip()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one source match, found {count}")
    return text.replace(old, new, 1)


def preflight(repo: Path) -> None:
    branch = run(repo, "git", "branch", "--show-current").stdout.strip()
    if branch != EXPECTED_BRANCH:
        raise RuntimeError(f"wrong branch: {branch!r}; expected {EXPECTED_BRANCH!r}")

    bad = {}
    for rel, expected in EXPECTED_BLOBS.items():
        path = repo / rel
        if not path.is_file():
            bad[rel] = {"expected": expected, "actual": "MISSING"}
            continue
        actual = git_blob_sha(repo, rel)
        if actual != expected:
            bad[rel] = {"expected": expected, "actual": actual}
    if bad:
        raise RuntimeError(
            "Refusing to apply V3 on an unexpected scientific state. "
            "No source file was changed. Blob mismatches:\n"
            + json.dumps(bad, indent=2, sort_keys=True)
        )

    for rel in EXPECTED_BLOBS:
        p = run(repo, "git", "diff", "--quiet", "HEAD", "--", rel, check=False)
        if p.returncode != 0:
            raise RuntimeError(
                f"{rel} already has uncommitted changes; refusing to stack repairs"
            )


def write_payloads(repo: Path) -> list[str]:
    written = []
    for rel, encoded in PAYLOADS_B64.items():
        path = repo / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(base64.b64decode(encoded))
        written.append(rel)
    return written


def patch_james_hane(repo: Path) -> str:
    rel = "src/cualni_cryst/james_hane.py"
    path = repo / rel
    text = path.read_text(encoding="utf-8")
    text = replace_once(text, JAMES_HANE_OLD, JAMES_HANE_NEW, "James-Hane Eq.25 domain guard")
    path.write_text(text, encoding="utf-8")
    return rel


def source_guards(repo: Path) -> None:
    ct = (repo / "src/cualni_cryst/ct.py").read_text(encoding="utf-8")
    required = [
        "A = C.T @ M_m @ C - M_a",
        "G = W @ (C.T @ M_m @ C) @ W",
        "return adaptive_smc(M_a, M_m, C)",
        "np.sqrt(vals[ip]) * V[:, ip]",
    ]
    missing = [x for x in required if x not in ct]
    if missing:
        raise RuntimeError(f"equation-preservation source guard failed: {missing}")

    cofactor = (repo / "src/cualni_cryst/cofactor.py").read_text(encoding="utf-8").replace(" ", "")
    if "np.trace(U2)-np.linalg.det(U2)-0.25" not in cofactor:
        raise RuntimeError("cofactor CC3 minus-det source guard failed")

    ptmc = (repo / "src/cualni_cryst/ptmc.py").read_text(encoding="utf-8")
    if "hidden\n    ``1e-6`` acceptance is removed" not in ptmc and "hidden ``1e-6`` acceptance is removed" not in ptmc:
        raise RuntimeError("PTMC hidden-tolerance guard missing")


def compile_changed(repo: Path, paths: list[str]) -> None:
    failures = []
    for rel in paths:
        path = repo / rel
        if path.suffix != ".py":
            continue
        try:
            compile(path.read_text(encoding="utf-8"), rel, "exec")
        except Exception as exc:
            failures.append({"path": rel, "error": repr(exc)})
    if failures:
        raise RuntimeError("generated Python did not compile:\n" + json.dumps(failures, indent=2))


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=".")
    args = ap.parse_args()
    repo = Path(args.repo).resolve()

    preflight(repo)
    written = write_payloads(repo)
    written.append(patch_james_hane(repo))
    source_guards(repo)
    compile_changed(repo, written)

    diff_check = run(repo, "git", "diff", "--check", check=False)
    if diff_check.returncode != 0:
        raise RuntimeError("git diff --check failed:\n" + diff_check.stdout + diff_check.stderr)

    manifest = {}
    for rel in sorted(set(written)):
        manifest[rel] = hashlib.sha256((repo / rel).read_bytes()).hexdigest()
    out = Path("/tmp/equation_preserving_v3_install_manifest.json")
    out.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")

    print("V3 generated source installed into the Actions working tree.")
    print("Scientific compatibility tolerance changed: NO")
    print("CMC source equation changed: NO")
    print("SMC definition changed: NO")
    print("Ball-James theorem/formulas changed: NO")
    print("PTMC determinant equation changed: NO")
    print("Arithmetic precision / stable algebraic route changed: YES")
    print("manifest:", out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
